改用带盐的自适应算法，例如 bcrypt / argon2-cffi / passlib CryptContext：

from passlib.hash import bcrypt

def hash_password(password):
    return bcrypt.hash(password)

def verify_password(password, hashed):
    return bcrypt.verify(password, hashed)
注意校验方式需从 == 改为 verify，天然避免时序比较问题。

在 login 中把用户不存在统一按认证失败处理，避免异常外泄：

def login(username, password):
    if not username or not password:
        return None
    try:
        user = find_user(username)
    except LookupError:
        return None
    if not user.is_active:
        return None
    if not hmac.compare_digest(user.password_hash, hash_password(password)):
        return None
    return _issue_token(user)

按「账号 + 来源 IP」维度做滑动窗口限流，例如：

from user_login_guard import register_failure, is_locked

def handle_login(request):
    key = (request.get("username"), request.get("ip"))
    if is_locked(key):
        return {"status": 429, "message": "尝试过于频繁，请稍后再试"}
    token = login(request.get("username"), request.get("password"))
    if token is None:
        register_failure(key)
        return {"status": 401, "message": "用户名或密码错误"}
    return {"status": 200, "token": token}
并记录登录失败审计日志。

